#!/usr/bin/env bash
# Install xkeyboard-config data into app/src/main/assets/xkb.
#
# libxkbcommon (statically linked into libwayland_compositor.so) reads keymap
# definitions from XKB_CONFIG_ROOT. The compositor cannot read APK assets, so
# XkbData.kt copies this tree out on first start.
#
# Upstream ships `rules/` only as `.part` fragments; `rules/evdev` and the
# `.lst`/`.xml` companions are generated by xkeyboard-config's own meson build,
# so this runs that build and keeps only the generated files.
#
# The directory is generated, not committed (see .gitignore).
set -euo pipefail

VERSION="${XKEYBOARD_CONFIG_VERSION:-2.44}"
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DEST_DIR="$ROOT_DIR/app/src/main/assets/xkb"
WORK_DIR="$(mktemp -d /tmp/xkbdata-XXXXXX)"
trap 'rm -rf "$WORK_DIR"' EXIT

URL="https://gitlab.freedesktop.org/xkeyboard-config/xkeyboard-config/-/archive/xkeyboard-config-$VERSION/xkeyboard-config-xkeyboard-config-$VERSION.tar.gz"
echo "==> Fetching xkeyboard-config $VERSION"
curl -fsSL --retry 2 -o "$WORK_DIR/xkbdata.tar.gz" "$URL"
tar xzf "$WORK_DIR/xkbdata.tar.gz" -C "$WORK_DIR"

SRC_DIR="$(ls -d "$WORK_DIR"/xkeyboard-config-* | head -n 1)"
if [[ ! -d "$SRC_DIR/symbols" ]]; then
    echo "unexpected archive layout in $SRC_DIR" >&2
    exit 1
fi

echo "==> Generating rules"
meson setup "$WORK_DIR/build" "$SRC_DIR" -Dcompat-rules=true >/dev/null
ninja -C "$WORK_DIR/build" \
    rules/evdev rules/base \
    rules/evdev.lst rules/base.lst \
    rules/evdev.xml rules/base.xml >/dev/null

rm -rf "$DEST_DIR"
mkdir -p "$DEST_DIR/rules"
# Only what libxkbcommon's keymap compiler resolves; locale, tests and build
# files stay out to keep the APK small.
for dir in compat keycodes symbols types; do
    cp -a "$SRC_DIR/$dir" "$DEST_DIR/$dir"
done
cp "$SRC_DIR/rules/xkb.dtd" "$DEST_DIR/rules/"
for file in evdev base; do
    for suffix in "" .lst .xml; do
        cp "$WORK_DIR/build/rules/$file$suffix" "$DEST_DIR/rules/"
    done
done
for file in evdev.extras.xml base.extras.xml; do
    if [[ -f "$WORK_DIR/build/rules/$file" ]]; then
        cp "$WORK_DIR/build/rules/$file" "$DEST_DIR/rules/"
    fi
done

echo "==> Done: $DEST_DIR"
du -sh "$DEST_DIR"
